// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceShellCallbacks {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceShellCallbacks = UniffiVTableCallbackInterfaceShellCallbacks(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeShellCallbacks.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface ShellCallbacks: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeShellCallbacks.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ShellCallbacks: handle missing in uniffiClone")
            }
        },
        onData: { (
            uniffiHandle: UInt64,
            data: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeShellCallbacks.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onData(
                     data: try FfiConverterData.lift(data)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        onExit: { (
            uniffiHandle: UInt64,
            exitCode: RustBuffer,
            exitSignal: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeShellCallbacks.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onExit(
                     exitCode: try FfiConverterOptionUInt32.lift(exitCode),
                     exitSignal: try FfiConverterOptionString.lift(exitSignal)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceShellCallbacks> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceShellCallbacks>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitShellCallbacks() {
    uniffi_termix_ssh_core_fn_init_callback_vtable_shellcallbacks(UniffiCallbackInterfaceShellCallbacks.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeShellCallbacks: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<ShellCallbacks>()

    typealias FfiType = UInt64
    typealias SwiftType = ShellCallbacks

    public static func lift(_ handle: UInt64) throws -> ShellCallbacks {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ShellCallbacksImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: ShellCallbacks) -> UInt64 {
         if let rustImpl = value as? ShellCallbacksImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ShellCallbacks {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ShellCallbacks, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


