    case AuthMethodNotAvailable(msg: String
    )
    case AuthCancelled
    case Cancelled
    case Timeout
    case Channel(msg: String
    )
    case Sftp(msg: String
    )
    case Io(msg: String
    )
    case Disconnected

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
